def choose_move(observation):
    def pos(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return default

    def step_toward(a, b):
        ax, ay = a
        bx, by = b
        dx = 0 if bx == ax else (1 if bx > ax else -1)
        dy = 0 if by == ay else (1 if by > ay else -1)
        return [dx, dy]

    def dist1(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def best_by_dist(items, ref, mode="min"):
        best_item = None
        best_score = None
        for it in items:
            p = pos(it, None)
            if p is None:
                continue
            s = dist1(p, ref)
            if best_item is None or (mode == "min" and s < best_score) or (mode == "max" and s > best_score):
                best_item = p
                best_score = s
        return best_item

    env = observation.get("environment_name", "resource_collection")
    sx, sy = pos(observation.get("self_position"), (0, 0))
    ox, oy = pos(observation.get("opponent_position"), (sx, sy))
    self_pos = (sx, sy)
    opp_pos = (ox, oy)

    gw = observation.get("grid_width", 0)
    gh = observation.get("grid_height", 0)
    if not isinstance(gw, int):
        gw = 0
    if not isinstance(gh, int):
        gh = 0

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(self_pos, opp_pos)
        corners = [(0, 0), (0, max(0, gh - 1)), (max(0, gw - 1), 0), (max(0, gw - 1), max(0, gh - 1))]
        target = None
        best = None
        for c in corners:
            s = dist1(c, opp_pos)
            if target is None or s > best:
                target = c
                best = s
        if target is not None:
            return step_toward(self_pos, target)
        return [-1 if sx > ox else (1 if sx < ox else 0), -1 if sy > oy else (1 if sy < oy else 0)]

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("neutral_cells") or []
        t = best_by_dist(targets, self_pos, "min")
        if t is not None:
            return step_toward(self_pos, t)
        # fallback: move toward opponent or center
        if gw > 0 and gh > 0:
            return step_toward(self_pos, (gw // 2, gh // 2))
        return step_toward(self_pos, opp_pos)

    resources = observation.get("resources") or observation.get("resource_positions") or []
    if resources:
        t = best_by_dist(resources, self_pos, "min")
        if t is not None:
            return step_toward(self_pos, t)

    # Fallbacks for any mode: prefer pressure/space based on opponent distance
    if env == "pursuit_evasion":
        return step_toward(self_pos, opp_pos)

    if gw > 0 and gh > 0:
        center = (gw // 2, gh // 2)
        if dist1(self_pos, opp_pos) <= 2:
            # drift away from opponent
            away = (sx + (1 if sx >= ox else -1), sy + (1 if sy >= oy else -1))
            return step_toward(self_pos, away)
        return step_toward(self_pos, center)

    return [0, 0]

